import React from 'react';
import { useNavigate } from 'react-router-dom';

export default function LiveReportMap({ reports }) {
  const navigate = useNavigate();
  return <section className="panel map-panel"><div className="panel-heading"><div><h2>Incident map</h2><p>Live environmental reports across Malawi</p></div><button className="select-like">This week⌄</button></div><div className="map"><div className="map-river"/><div className="map-road road-one"/><div className="map-road road-two"/><div className="map-label label-lilongwe">LILONGWE</div><div className="map-label label-mzuzu">MZUZU</div><div className="map-label label-zomba">ZOMBA</div><div className="map-label label-blantyre">BLANTYRE</div>{reports.filter(report => report.status !== 'RESOLVED').map((report, index) => <button key={report.id} title={`${report.id} · ${report.category}`} onClick={() => navigate(`/reports/${report.id}`)} className={`map-pin pin-${report.severity.toLowerCase()} pin-${index}`}><span/></button>)}<div className="map-credit">Map data © OpenStreetMap contributors</div><button className="map-expand" title="Expand map">⛶</button></div><div className="map-legend"><span><i className="dot critical"/>Critical</span><span><i className="dot high"/>High</span><span><i className="dot medium"/>Medium</span><span><i className="dot low"/>Low</span><span className="map-count">{reports.filter(report => report.status !== 'RESOLVED').length} active reports</span></div></section>;
}
